function LivePrice({ symbol, onTick }: { symbol: string; onTick: (p: number) => void }) {
  const [price, setPrice] = useState<number | null>(null);

  useEffect(() => {
    let ignore = false;
    const id = setInterval(async () => {
      const p = await fetchPrice(symbol);
      if (!ignore) {
        setPrice(p);
        onTick(p);
      }
    }, 1000);
    // no cleanup of the interval
  }, [symbol]);

  useEffect(() => {
    const sub = priceFeed.subscribe(symbol, setPrice);
    return () => sub.unsubscribe();
  }, []);

  return <span>{price ?? "--"}</span>;
}
